fn pattern0(input: &[u16]) -> bool {
(0..=input.len()).any(|position| !pattern0_node0(input, position).is_empty())
}

fn pattern0_node1(_input: &[u16], position: usize) -> Vec<usize> {
if position == 0 { vec![position] } else { Vec::new() }
}

fn pattern0_node3(input: &[u16], position: usize) -> Vec<usize> {
if position == input.len() { return Vec::new(); }
let unit = input[position];
if unit <= 9 || unit >= 11 && unit <= 12 || unit >= 14 && unit <= 57 || unit >= 59 { vec![position + 1] } else { Vec::new() }
}

fn pattern0_node2(input: &[u16], position: usize) -> Vec<usize> {
let mut positions = vec![position];
let mut result = std::collections::BTreeSet::new();
let limit = (input.len() - position).saturating_add(1);
for count in 0..=limit {
    if positions.is_empty() { break; }
    if count >= 1 { result.extend(positions.iter().copied()); }
    if count == limit { break; }
    let mut next = std::collections::BTreeSet::new();
    for &start in &positions { next.extend(pattern0_node3(input, start)); }
    if next.len() == positions.len() && positions.iter().all(|end| next.contains(end)) {
        // Nullable repetition can be padded to its minimum without advancing.
        result.extend(next);
        break;
    }
    positions = next.into_iter().collect();
}
result.into_iter().collect()
}

fn pattern0_node4(input: &[u16], position: usize) -> Vec<usize> {
if position == input.len() { vec![position] } else { Vec::new() }
}

fn pattern0_node0(input: &[u16], position: usize) -> Vec<usize> {
let mut positions = vec![position];
{
let mut next = std::collections::BTreeSet::new();
for start in positions { next.extend(pattern0_node1(input, start)); }
positions = next.into_iter().collect();
if positions.is_empty() { return positions; }
}
{
let mut next = std::collections::BTreeSet::new();
for start in positions { next.extend(pattern0_node2(input, start)); }
positions = next.into_iter().collect();
if positions.is_empty() { return positions; }
}
{
let mut next = std::collections::BTreeSet::new();
for start in positions { next.extend(pattern0_node4(input, start)); }
positions = next.into_iter().collect();
if positions.is_empty() { return positions; }
}
positions
}


/// Check the request without consuming input or inserting defaults.
/// The returned checker owns only selection flags, not the request or its stream.
/// Pass None for the canonical "text" input, or Some(field) for a named input.
pub fn validate_request(value: &TtsRequest) -> Result<impl Fn(&dyn std::any::Any, Option<&str>) -> Result<(), ValidationError>, ValidationError> {
    if !valid0(value) { return Err(ValidationError("Invalid microsoft TTS request")); }
let accepts0 = match value {
TtsRequest::DragonHdFlashTextVoice(_) => false,
TtsRequest::DragonHdFlashStreamingTextVoice(_) => true,
TtsRequest::DragonHdTextVoice(_) => false,
TtsRequest::DragonHdStreamingTextVoice(_) => true,
TtsRequest::TextVoice7173695c(_) => false,
TtsRequest::StreamingTextVoice114e3a08(_) => true,
TtsRequest::TextVoice5b29fe90(_) => false,
TtsRequest::StreamingTextVoice28b31a28(_) => true,
TtsRequest::TextVoicee024151d(_) => false,
TtsRequest::DragonHdOmniTextVoice04791425(_) => false,
TtsRequest::DragonHdOmniStreamingTextVoice(_) => true,
TtsRequest::DragonHdOmniTextVoice8ad9713d(_) => false,
TtsRequest::Text869f3eb8(_) => false,
TtsRequest::Text0f18f35c(_) => false,
};
    Ok(move |item: &dyn std::any::Any, field: Option<&str>| {
        let field = field.unwrap_or("text");
        if accepts0 && field == "text" && item.downcast_ref().map_or(false, valid2) { Ok(()) } else { Err(ValidationError("Invalid microsoft TTS input item")) }
    })
}
